checks.command:
/bin/zsh -lc "rtk python3 -c 'import json; q=json.load(open(\"QA/CHG-232/comparative/objective_comparison.json\")); print(\"top\",[(k,type(v).__name__) for k,v in q.items()]); print(\"candidate\",json.dumps(q.get(\"candidate_interactions\",{}).get(\"checks\",{}),indent=2)); print(\"variant ids\",[(k,v.get(\"revision\"),v.get(\"tree\")) for k,v in q.get(\"matched_variants\",{}).items()]);
for f in [\"QA/CHG-232/decision_workbench/task_oracles.json\",\"QA/CHG-232/place_list_roles.json\"]:
 p=json.load(open(f)); print(f,{k:p.get(k) for k in [\"status\",\"candidate\",\"candidate_tree\",\"errors\",\"failures\"]})
' && rtk rg -n 'FOCUS_DATE|FOCUS_REGION|geometry|SOURCE_POLICY|ACTIVE_PACKAGE' scripts/qa_config.py scripts/qa_gate4_resilience.py && rtk sed -n '1,105p' scripts/qa_gate4_resilience.py && rtk rg -n 'today_plan_oracle_next_protected_nap_and_critical_condition|matched_variants|candidate_interactions|endpoint_signature_matches|objective_comparison' scripts"

/bin/zsh -lc "rtk python3 -c 'import json,statistics; q=json.load(open(\"QA/CHG-232/release/qualification.json\")); g=json.load(open(\"QA/CHG-232/gate5/candidate.json\")); p=g[\"performance\"]; print(\"qualification keys\",list(q)); print(\"qualification\",json.dumps({k:v for k,v in q.items() if k not in [\"component_results\",\"tests\",\"components\"]},indent=2)[:4500]); print(\"gate5 keys\",list(g)); print(\"perf delta\",json.dumps(p.get(\"summary\") or p.get(\"comparison\") or {},indent=2)[:3500]);
for metric in [\"dom_content_ms\",\"smart_style_ready_ms\",\"first_actionable_state_ms\"]:
 a=[x[metric] for x in p[\"baseline\"][\"samples\"]]; b=[x[metric] for x in p[\"candidate\"][\"samples\"]]; print(metric,\"baseline median\",round(statistics.median(a),1),\"candidate median\",round(statistics.median(b),1),\"delta\",round(statistics.median(b)-statistics.median(a),1),\"pct\",round((statistics.median(b)/statistics.median(a)-1)*100,1))
print(\"performance status\",p.get(\"status\"),p.get(\"comparison_status\"),\"qual verify\",g.get(\"verify_required\"))' && rtk git status --short | rtk rg -v '"'^.. QA/'"' && rtk git log --oneline --decorate -4 && rtk git diff --name-status b260a0b4c38220f89af2e3b6772c46b5afc63c42..HEAD && rtk git rev-parse HEAD && rtk git rev-parse HEAD"'^{tree}'

/bin/zsh -lc "rtk python3 -c 'import json,hashlib; from pathlib import Path; root=Path(\".\"); files=[\"QA/CHG-232/release/fast.json\",\"QA/CHG-232/release/qualification.json\",\"QA/CHG-232/gate5/candidate.json\",\"QA/CHG-232/release/gate4_runtime.json\",\"QA/CHG-232/portability.json\",\"QA/CHG-232/phone_field_surface.json\"]; reports={};
for f in files:
 p=json.load(open(f)); reports[f]={\"status\":p.get(\"status\"),\"candidate_head\":p.get(\"candidate_head\"),\"candidate_tree\":p.get(\"candidate_tree\"),\"failures\":p.get(\"failures\"),\"verify_required\":p.get(\"verify_required\")}
phone=json.load(open(files[-1])); reports[\"phone_route_views\"]={k:{x:phone[\"surfaces\"][k][x] for x in [\"date\",\"map_markers\",\"route_features\",\"next_item_visible_px\",\"horizontal_overflow\"]} for k in [\"sf_route_390x844\",\"sf_route_320x800\"]}; inv=Path(\"QA/CHG-232/changed_files.txt\").read_text().splitlines(); reports[\"changed_path_count\"]=len(inv); reports[\"record_exists\"]=Path(\"QA/CHG-232/BUILD_RECORD.md\").is_file(); print(json.dumps(reports,indent=2))'"
